"""matplotlib.projections.geo — geographic projection stubs.

Real matplotlib supports Aitoff/Hammer/Mollweide/Lambert projections.
The plotly backend has its own choropleth/scattergeo support, so these
classes exist purely to satisfy ``from matplotlib.projections.geo
import GeoAxes`` imports.
"""

from matplotlib.axes._axes import Axes


import numpy as _np


class GeoAxes(Axes):
    """Base class for all geographic projections (longitude/latitude
    axes). Subclasses override :meth:`_transform` to map (lon, lat) in
    radians to display coordinates."""

    RESOLUTION = 75
    name = 'geo'

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        # Default grid every 30° longitude / 10° latitude (matches upstream).
        self._lon_grid = 30.0
        self._lat_grid = 10.0
        self._lon_grid_ends = 75.0  # latitude limit for longitude grid lines

    def set_longitude_grid(self, degrees):
        """Set how often longitude grid lines are drawn (in degrees)."""
        self._lon_grid = float(degrees)

    def set_latitude_grid(self, degrees):
        self._lat_grid = float(degrees)

    def set_longitude_grid_ends(self, degrees):
        """Latitude at which longitude grid lines stop (Aitoff /
        Hammer use this to keep poles uncluttered)."""
        self._lon_grid_ends = float(degrees)

    def get_xlim(self): return (-_np.pi, _np.pi)
    def get_ylim(self): return (-_np.pi / 2, _np.pi / 2)

    def _transform(self, lon, lat):
        """Identity — subclasses override."""
        return lon, lat


class AitoffAxes(GeoAxes):
    """Aitoff equal-area projection.
    ``x = 2 cos(lat) sin(lon/2) / sinc(alpha)``,
    ``y = sin(lat) / sinc(alpha)``,
    where ``alpha = acos(cos(lat) cos(lon/2))``."""

    name = 'aitoff'

    def _transform(self, lon, lat):
        lon = _np.asarray(lon, dtype=float)
        lat = _np.asarray(lat, dtype=float)
        half_lon = lon / 2.0
        alpha = _np.arccos(_np.clip(_np.cos(lat) * _np.cos(half_lon), -1, 1))
        # sinc here is unnormalized: sin(α)/α — use _np.sinc with /pi adjustment.
        with _np.errstate(divide='ignore', invalid='ignore'):
            sinc_alpha = _np.where(alpha == 0, 1.0, _np.sin(alpha) / alpha)
        x = 2 * _np.cos(lat) * _np.sin(half_lon) / sinc_alpha
        y = _np.sin(lat) / sinc_alpha
        return x, y


class HammerAxes(GeoAxes):
    """Hammer equal-area projection.
    ``x = 2 sqrt(2) cos(lat) sin(lon/2) / sqrt(1 + cos(lat) cos(lon/2))``,
    ``y = sqrt(2) sin(lat) / sqrt(1 + cos(lat) cos(lon/2))``."""

    name = 'hammer'

    def _transform(self, lon, lat):
        lon = _np.asarray(lon, dtype=float)
        lat = _np.asarray(lat, dtype=float)
        half_lon = lon / 2.0
        denom = _np.sqrt(1.0 + _np.cos(lat) * _np.cos(half_lon))
        x = 2 * _np.sqrt(2) * _np.cos(lat) * _np.sin(half_lon) / denom
        y = _np.sqrt(2) * _np.sin(lat) / denom
        return x, y


class MollweideAxes(GeoAxes):
    """Mollweide pseudo-cylindrical equal-area projection. Requires
    iterating for the auxiliary angle θ where ``2θ + sin(2θ) = π sin(lat)``."""

    name = 'mollweide'

    def _transform(self, lon, lat):
        lon = _np.asarray(lon, dtype=float)
        lat = _np.asarray(lat, dtype=float)
        # Newton-Raphson for θ.
        theta = _np.array(lat, copy=True)
        for _ in range(10):
            num = 2 * theta + _np.sin(2 * theta) - _np.pi * _np.sin(lat)
            denom = 2 + 2 * _np.cos(2 * theta)
            theta = theta - num / _np.where(denom == 0, 1e-9, denom)
        x = (2 * _np.sqrt(2) / _np.pi) * lon * _np.cos(theta)
        y = _np.sqrt(2) * _np.sin(theta)
        return x, y


class LambertAxes(GeoAxes):
    """Lambert azimuthal equal-area projection, centered at the
    instance's (``center_longitude``, ``center_latitude``) — defaults
    to (0, 0)."""

    name = 'lambert'

    def __init__(self, *args, center_longitude=0, center_latitude=0, **kwargs):
        super().__init__(*args, **kwargs)
        self.center_longitude = float(center_longitude)
        self.center_latitude = float(center_latitude)

    def _transform(self, lon, lat):
        lon = _np.asarray(lon, dtype=float)
        lat = _np.asarray(lat, dtype=float)
        c_lon = self.center_longitude
        c_lat = self.center_latitude
        d_lon = lon - c_lon
        k = _np.sqrt(2 / _np.maximum(
            1 + _np.sin(c_lat) * _np.sin(lat)
              + _np.cos(c_lat) * _np.cos(lat) * _np.cos(d_lon),
            1e-9))
        x = k * _np.cos(lat) * _np.sin(d_lon)
        y = k * (_np.cos(c_lat) * _np.sin(lat)
                  - _np.sin(c_lat) * _np.cos(lat) * _np.cos(d_lon))
        return x, y
